interface Message {
  role: 'user' | 'assistant';
  content: string;
  /** assistant 메시지의 서버 ID (done event에서 받음). reaction 호출에 사용. */
  id?: string;
  /** 1 = like, -1 = dislike, undefined = 미반응. */
  reaction?: 1 | -1;
  /** 신고 완료 표시 (UI 잠금) — 서버 응답 200 받은 후 true. */
  reported?: boolean;
  /** 진행 단계 표시 — 첫 delta 도착 또는 done 시 비워짐. */
  progress?: ProgressState;
}

/** SSE progress 이벤트로 갱신되는 상태 — UI 상단 status 라인. */
